input.command:
MERCHANT_ID=$(grep '^XSOLLA_MERCHANT_ID=' /Users/raufaliyev/GolandProjects/xsolla-ai-kit/.env | cut -d= -f2)
PROJECT_ID=$(grep '^XSOLLA_PROJECT_ID=' /Users/raufaliyev/GolandProjects/xsolla-ai-kit/.env | cut -d= -f2)
API_KEY=$(grep '^XSOLLA_PROJECT_API_KEY=' /Users/raufaliyev/GolandProjects/xsolla-ai-kit/.env | cut -d= -f2)

AUTH=$(echo -n "$MERCHANT_ID:$API_KEY" | base64)
PUBLIC_BASE="https://quests-stage.xsolla.com"

# Generate UUIDs for nodes
TRIGGER_NODE_ID=$(python3 -c "import uuid; print(str(uuid.uuid4()))")
REWARD_NODE_ID=$(python3 -c "import uuid; print(str(uuid.uuid4()))")

echo "Trigger node ID: $TRIGGER_NODE_ID"
echo "Reward node ID: $REWARD_NODE_ID"

# Create the quest document
QUEST_JSON=$(cat <<'EOF'
{
  "name": "Tutorial Completion Quest",
  "type": "liveops",
  "status": "inactive",
  "created_by": "AI Toolkit",
  "description": "Quest that rewards players for completing the tutorial",
  "nodes": [
    {
      "id": "TRIGGER_ID",
      "name": "Player completes tutorial",
      "type": "trigger",
      "subtype": "dynamic_event",
      "parameters": {
        "event_name": "tutorial_completed"
      }
    },
    {
      "id": "REWARD_ID",
      "name": "Award tutorial reward",
      "type": "action",
      "subtype": "issue_reward",
      "parameters": {
        "type": "web3_item",
        "purpose": "quest_completion",
        "body": {
          "project": "316665",
          "item_sku": "quest_demo_r2h_20260930t1923z",
          "quantity": 1
        }
      }
    }
  ],
  "connections": {
    "TRIGGER_ID": [
      {
        "nodeId": "REWARD_ID"
      }
    ]
  },
  "activation_limits": [
    {
      "type": "per_user",
      "count": 1
    }
  ]
}
EOF
)

# Replace placeholders with actual UUIDs
QUEST_JSON=${QUEST_JSON//TRIGGER_ID/$TRIGGER_NODE_ID}
QUEST_JSON=${QUEST_JSON//REWARD_ID/$REWARD_NODE_ID}

echo "Creating quest..."
QUEST_RESPONSE=$(curl -s -X POST \
  "$PUBLIC_BASE/api/v2/merchants/$MERCHANT_ID/projects/$PROJECT_ID/quests" \
  -H "Authorization: Basic $AUTH" \
  -H "Content-Type: application/json" \
  -d "$QUEST_JSON")

echo "$QUEST_RESPONSE" | jq '.'

QUEST_ID=$(echo "$QUEST_RESPONSE" | jq -r '.id')
echo "Quest ID: $QUEST_ID"

